  page_description: ["PlastiSense AI - Detect plastic waste from imagery, predict drain-to-sea leakage hotspots, optimize municipal cleanups, and protect Mumbai's coastline.", "PlastiSense AI - படங்களிலிருந்து பிளாஸ்டிக் கழிவைக் கண்டறிந்து, வடிகாலிலிருந்து கடலுக்குச் செல்லும் கசிவு பகுதிகளைக் கணித்து, நகராட்சி சுத்தப்படுத்தலை மேம்படுத்தி, மும்பைக் கடற்கரையைப் பாதுகாக்கிறது.", "PlastiSense AI - చిత్రాల నుంచి ప్లాస్టిక్ వ్యర్థాలను గుర్తించి, డ్రెయిన్ నుంచి సముద్రానికి చేరే లీకేజీ హాట్‌స్పాట్‌లను అంచనా వేసి, మున్సిపల్ శుభ్రతను మెరుగుపరచి ముంబై తీరాన్ని రక్షిస్తుంది.", "PlastiSense AI - ಚಿತ್ರಗಳಿಂದ ಪ್ಲಾಸ್ಟಿಕ್ ತ್ಯಾಜ್ಯ ಪತ್ತೆ, ಚರಂಡಿಯಿಂದ ಸಮುದ್ರಕ್ಕೆ ಸೋರಿಕೆ ಹಾಟ್‌ಸ್ಪಾಟ್ ಮುನ್ಸೂಚನೆ, ಪೌರ ಸ್ವಚ್ಛತಾ ಕಾರ್ಯ ಸುಧಾರಣೆ ಮತ್ತು ಮುಂಬೈ ಕರಾವಳಿ ರಕ್ಷಣೆ.", "PlastiSense AI - ചിത്രങ്ങളിൽ നിന്ന് പ്ലാസ്റ്റിക് മാലിന്യം കണ്ടെത്തി, ഡ്രെയിനിൽ നിന്ന് കടലിലേക്കുള്ള ചോർച്ചാ കേന്ദ്രങ്ങൾ പ്രവചിച്ച്, മുനിസിപ്പൽ ശുചീകരണം മെച്ചപ്പെടുത്തി മുംബൈ തീരം സംരക്ഷിക്കുന്നു.", "PlastiSense AI - चित्रों से प्लास्टिक कचरे की पहचान, नाली से समुद्र तक रिसाव हॉटस्पॉट का अनुमान, नगरपालिका सफाई का अनुकूलन और मुंबई तट की सुरक्षा।"],
