  ui_forecast_no_wards: ["No wards have verified inputs available for this forecast period. Demo measurements are not substituted.", "இந்த முன்னறிவிப்பு காலத்திற்கு சரிபார்க்கப்பட்ட உள்ளீடுகள் உள்ள வார்டுகள் இல்லை. டெமோ அளவீடுகள் மாற்றாகப் பயன்படுத்தப்படாது.", "ఈ అంచనా కాలానికి ధృవీకరించిన ఇన్‌పుట్‌లు ఉన్న వార్డులు లేవు. డెమో కొలతలను ప్రత్యామ్నాయంగా ఉపయోగించము.", "ಈ ಮುನ್ಸೂಚನೆ ಅವಧಿಗೆ ಪರಿಶೀಲಿತ ಇನ್‌ಪುಟ್‌ಗಳಿರುವ ವಾರ್ಡ್‌ಗಳಿಲ್ಲ. ಡೆಮೋ ಅಳತೆಗಳನ್ನು ಬದಲಿಯಾಗಿ ಬಳಸುವುದಿಲ್ಲ.", "ഈ പ്രവചന കാലയളവിൽ പരിശോധിച്ച ഇൻപുട്ടുകളുള്ള വാർഡുകളില്ല. ഡെമോ അളവുകൾ പകരം ഉപയോഗിക്കില്ല.", "इस पूर्वानुमान अवधि के लिए सत्यापित इनपुट वाले वार्ड उपलब्ध नहीं हैं। डेमो मापों को विकल्प के रूप में नहीं दिखाया जाएगा।"],
