  ui_ai_verified: ["AI VERIFIED", "AI சரிபார்த்தது", "AI ధృవీకరించింది", "AI ಪರಿಶೀಲಿಸಿದೆ", "AI പരിശോധിച്ചു", "AI सत्यापित"],
