  ui_insufficient_evidence: ["INSUFFICIENT EVIDENCE", "போதுமான ஆதாரம் இல்லை", "తగిన ఆధారాలు లేవు", "ಸಾಕಷ್ಟು ಪುರಾವೆಗಳಿಲ್ಲ", "മതിയായ തെളിവില്ല", "अपर्याप्त साक्ष्य"],
