  ui_baseline_leakage: ["Estimated Baseline Leakage for Scenario (kg, chosen period)", "சூழ்நிலைக்கான மதிப்பிடப்பட்ட அடிப்படை கசிவு (கிலோ, தேர்ந்தெடுத்த காலம்)", "సన్నివేశానికి అంచనా ప్రాథమిక లీకేజీ (కిలో, ఎంచుకున్న కాలం)", "ಸನ್ನಿವೇಶದ ಅಂದಾಜು ಮೂಲ ಸೋರಿಕೆ (ಕೆ.ಜಿ., ಆಯ್ದ ಅವಧಿ)", "സാഹചര്യത്തിലെ കണക്കാക്കിയ അടിസ്ഥാന ചോർച്ച (കി.ഗ്രാം, തിരഞ്ഞെടുത്ത കാലയളവ്)", "परिदृश्य के लिए अनुमानित आधारभूत रिसाव (किग्रा, चुनी अवधि)"],
