  ui_add_comparison: ["Add to Comparison", "ஒப்பீட்டில் சேர்", "పోలికకు జోడించండి", "ಹೋಲಿಕೆಗೆ ಸೇರಿಸಿ", "താരതമ്യത്തിലേക്ക് ചേർക്കുക", "तुलना में जोड़ें"],
