  ui_analyze_brands: ["Analyze Visible Brands", "காணப்படும் பிராண்டுகளைப் பகுப்பாய்வு செய்", "కనిపించే బ్రాండ్‌లను విశ్లేషించండి", "ಕಾಣುವ ಬ್ರ್ಯಾಂಡ್‌ಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ", "കാണുന്ന ബ്രാൻഡുകൾ വിശകലനം ചെയ്യുക", "दिखने वाले ब्रांडों का विश्लेषण करें"],
